mapper.select:
SELECT 
FROM orbit_system_configuration
WHERE tenant_id = #{tenantId} AND id = #{id}

SELECT id, actor_id, action, revision, before_revision, before_hash, after_hash, hash_algorithm, changed_fields_json, reason, created_at
FROM orbit_configuration_audit
WHERE tenant_id = #{tenantId} AND config_id = #{configId}
    AND revision < #{beforeRevision}
ORDER BY revision DESC
LIMIT #{limit}

mapper.insert:
INSERT INTO orbit_configuration_audit (
    id, tenant_id, config_id, actor_id, action, revision, before_revision, before_hash, after_hash, hash_algorithm, changed_fields_json, reason, created_at
) VALUES (
    #{id}, #{tenantId}, #{configId}, #{actorId}, #{action}, #{revision}, #{beforeRevision}, #{beforeHash}, #{afterHash}, #{hashAlgorithm}, #{changedFieldsJson}, #{reason}, UTC_TIMESTAMP(3)
)

mapper.update:
UPDATE orbit_configuration_idempotency
SET response_json = #{responseJson}
WHERE tenant_id = #{tenantId} AND actor_id = #{actorId} AND request_key = #{requestKey}
